    current_diff = abs(current_bottom_area - target_bottom_area)

    # Timing-criticality per macro (optional): when provided, a macro that
    # touches many critical nets is "expensive" to move across tiers, so we
    # require a larger area improvement before accepting its move. This keeps
    # balance repair from cutting critical paths. Falls back to uniform when
    # no criticality is supplied.
    crit = getattr(_refine_partition_by_area, '_macro_criticality', None)
    if crit is not None:
        try:
            crit = np.asarray(crit, dtype=np.float64)
            cmin, cmax = float(crit.min()), float(crit.max())
            if cmax > cmin:
                crit = (crit - cmin) / (cmax - cmin)  # normalize to [0,1]
            else:
                crit = None
        except Exception:
            crit = None
    # Penalty factor: a fully-critical macro must yield this much more area
    # improvement to be moved than a non-critical one.
    crit_penalty = 3.0

    def _move_cost(macro_idx, raw_gain):
        """Effective gain after criticality penalty (higher = better)."""
        if crit is None:
            return raw_gain
        try:
            c = float(crit[macro_idx])
        except Exception:
            c = 0.0
        return raw_gain / (1.0 + crit_penalty * c)

